 static void Install(){Directory.CreateDirectory(Art);AssetDatabase.Refresh();Backup("ProjectSettings/TagManager.asset");if(RenderingLayerMask.GetRenderingLayerCount()==2)UnityEditor.Rendering.RenderPipelineEditorUtility.TryAddRenderingLayerName("CombatReceivers");if(RenderingLayerMask.RenderingLayerToName(2)!="CombatReceivers")throw new Exception("Receiver rendering layer is occupied");
