 public static void ApplyForCurrentScene(string composer=null){var s=SceneManager.GetActiveScene();if(composer!="Monteverdi"&&!s.name.StartsWith("Monteverdi"))return;if(!AssetDatabase.LoadAssetAtPath<Material>(Art+"/LowContact.mat"))return;foreach(var r in s.GetRootGameObjects())if(r.GetComponentInChildren<ArenaCombatLook>(true))Apply(r,quality(s.name));}
 static void Apply(GameObject root,string q){var look=root.GetComponentInChildren<ArenaCombatLook>(true);if(!look)return;var previous=look.GetComponent<ArenaCharacterGrounding>();if(previous)Object.DestroyImmediate(previous);var old=look.transform.Find("CharacterGroundShadowKey");if(old)Object.DestroyImmediate(old.gameObject);var go=new GameObject("CharacterGroundShadowKey");go.transform.SetParent(look.transform,false);go.transform.position=(Quaternion.Euler(19,-55,0)*Vector3.back)*80f;go.transform.LookAt(new Vector3(0,0,0));var light=go.AddComponent<Light>();light.type=LightType.Spot;light.spotAngle=18;light.innerSpotAngle=16;light.range=120;light.intensity=q=="Mid"?10400:12000;light.color=new Color(1,.94f,.84f);light.shadows=LightShadows.Soft;light.shadowStrength=1f;light.shadowBias=.02f;light.shadowNormalBias=.06f;light.shadowNearPlane=50f;light.lightmapBakeType=LightmapBakeType.Realtime;light.renderMode=LightRenderMode.ForcePixel;var extra=light.GetUniversalAdditionalLightData();extra.renderingLayers=ArenaCharacterGrounding.ReceiverMask;extra.customShadowLayers=true;extra.shadowRenderingLayers=ArenaCombatLook.CharacterMask;extra.usePipelineSettings=false;extra.softShadowQuality=q=="Mid"?SoftShadowQuality.Low:SoftShadowQuality.Medium;var lightData=new SerializedObject(extra);lightData.FindProperty("m_AdditionalLightsShadowResolutionTier").intValue=q=="Mid"?1:2;lightData.ApplyModifiedPropertiesWithoutUndo();light.enabled=false;
 var component=look.gameObject.AddComponent<ArenaCharacterGrounding>();component.look=look;component.shadowKey=light;component.midPipeline=q=="Mid"?AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(Art+"/Mid_ContactShadows.asset"):null;component.lowContactMaterial=AssetDatabase.LoadAssetAtPath<Material>(Art+"/LowContact.mat");}
 static void UpgradeScenes(){foreach(string p in Directory.GetFiles(Root+"/Scenes","*.unity")){Backup(p);var s=EditorSceneManager.OpenScene(p,OpenSceneMode.Single);ApplyForCurrentScene("Monteverdi");EditorSceneManager.SaveScene(s);total++;}foreach(string p in Directory.GetFiles(Root,"Monteverdi_Arena_*.prefab")){Backup(p);var r=PrefabUtility.LoadPrefabContents(p);try{Apply(r,"Ultra");PrefabUtility.SaveAsPrefabAsset(r,p);}finally{PrefabUtility.UnloadPrefabContents(r);}}AssetDatabase.SaveAssets();ArenaBundleValidation.Register();log.Add("Production scenes upgraded="+total+"; two character lights remain shadowless; one environment-receiver/character-caster spot added.");}
