 static void Capture(string name,int w=1600,int h=900){float aspect=cam.aspect;cam.aspect=(float)w/h;var rt=new RenderTexture(w,h,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB){antiAliasing=4};rt.Create();cam.targetTexture=rt;for(int i=0;i<3;i++)cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(w,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,w,h),0,0);tex.Apply();File.WriteAllBytes(Work+"/captures/"+name+".png",tex.EncodeToPNG());RenderTexture.active=prev;cam.targetTexture=null;cam.aspect=aspect;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(tex);}
 static void Wait(int p,float seconds=1){phase=p;next=EditorApplication.timeSinceStartup+seconds;}
