 static void Tick(){try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Shadow review timed out at phase "+phase);if(phase==90){if(EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Tick;QualitySettings.renderPipeline=initialPipeline;EditorSettings.enterPlayModeOptionsEnabled=oldPlay;EditorSettings.enterPlayModeOptions=oldOptions;VerifySaved();File.WriteAllLines(Work+"/verification.txt",log);File.WriteAllText(Work+"/ready.txt","PASS dynamic character shadows on floor and object; Low fallback and Mid scoped shadow profile; lifecycle restored.");EditorApplication.Exit(0);return;}if(!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next||ShaderUtil.anythingCompiling)return;
 if(phase==0){actors=Object.FindFirstObjectByType<CombatLookPreviewActors>();if(!actors||!actors.Ready){if(actors&&!string.IsNullOrEmpty(actors.Error))throw new Exception(actors.Error);return;}actors.frozen=true;cam=actors.previewCamera;ground=actors.look.GetComponent<ArenaCharacterGrounding>();ground.Activate();ground.Register(actors.Player.Root);ground.Register(actors.Rival.Root);originalPlayer=actors.Player.Root.parent.position;foreach(var ps in Object.FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None)){ps.Simulate(1.2f,true,true);ps.Pause(true);}Audit();ground.shadowKey.enabled=false;Wait(1);return;}
