 if(phase==9){Capture("Motion_"+frame.ToString("00"),1100,620);frame++;if(frame<16){Wait(8,.04f);return;}actors.Player.Root.parent.position=originalPlayer;ground.enabled=false;QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/Quality/URP_Low.asset");ground.enabled=true;Wait(10);return;}
 if(phase==10){if(!ground.UsingContactFallback||ground.ActiveContactCount!=2||ground.shadowKey.enabled)throw new Exception("Low fallback failed");log.Add("PASS Low: two soft contact quads, no extra shadow atlas or light.");ground.enabled=false;QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/Quality/URP_Mid.asset");ground.midPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(Art+"/Mid_ContactShadows.asset");ground.enabled=true;Wait(11);return;}
 if(phase==11){if(ground.UsingContactFallback||!ground.shadowKey.enabled||QualitySettings.renderPipeline!=ground.midPipeline)throw new Exception("Mid pipeline activation failed");log.Add("PASS Mid: scoped 512px shadow atlas and character-only caster mask.");ground.enabled=false;actors.look.enabled=false;var floor=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MeshRenderer>(true)).First(r=>r.name=="Floor");if((floor.renderingLayerMask&ArenaCharacterGrounding.ReceiverMask)!=0)throw new Exception("Receiver mask not restored");log.Add("PASS lifecycle: receiver masks, caster settings and pipeline restored.");log.Add("High pilot lightmaps="+LightmapSettings.lightmaps.Length+" probes="+(LightmapSettings.lightProbes?LightmapSettings.lightProbes.count:0));EditorApplication.isPlaying=false;phase=90;return;}
