 static void MakeReceiver(){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Project/Art/Arenas/Pachelbel/Props/Pachelbel_scenario_ornamental_planter/HighMid/Pachelbel_scenario_ornamental_planter_HighMid.prefab");proofProp=Object.Instantiate(prefab);proofProp.name="ShadowReceiverProof_ExistingMarblePlanter";var r=proofProp.GetComponentInChildren<MeshRenderer>();var b=r.bounds;proofProp.transform.localScale*=.95f/b.size.y;b=r.bounds;proofProp.transform.position+=new Vector3(-2.25f-b.center.x,-b.min.y,.85f-b.center.z);foreach(var c in proofProp.GetComponentsInChildren<Collider>())c.enabled=false;r.renderingLayerMask|=ArenaCharacterGrounding.ReceiverMask;r.receiveShadows=true;cam.transform.position=new Vector3(-4.5f,2.1f,-2.5f);cam.transform.LookAt(new Vector3(-1.65f,.75f,.7f));cam.fieldOfView=40;}
 static void Audit(){var sun=Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.name=="ArenaSun");float angle=Vector3.Angle(-sun.transform.forward,ground.shadowKey.transform.position.normalized);if(angle>.1f)throw new Exception("Character shadow key differs from baked sun: "+angle);log.Add("PASS sun coherence: centre-ray difference="+angle+" degrees; sun azimuth125 elevation19; distant character shadow proxy80m, ring rays nearly parallel. Sky disc rotation39.19027 verticalOffset0.00751844 calibrated from image centroid.");foreach(var a in new[]{actors.Player,actors.Rival})foreach(var r in a.Root.GetComponentsInChildren<Renderer>()){if(r is ParticleSystemRenderer)continue;log.Add(r.name+" | cast="+r.shadowCastingMode+" | layer="+r.renderingLayerMask+" | shader="+string.Join(";",r.sharedMaterials.Where(m=>m).Select(m=>m.shader.name+":ShadowCaster="+m.GetShaderPassEnabled("ShadowCaster"))));}if(ground.UsingContactFallback)throw new Exception("High preview did not enable real shadow maps");var data=ground.shadowKey.GetUniversalAdditionalLightData();if(!data.customShadowLayers||(uint)data.renderingLayers!=ArenaCharacterGrounding.ReceiverMask||(uint)data.shadowRenderingLayers!=ArenaCombatLook.CharacterMask)throw new Exception("Shadow layer contract invalid");log.Add("PASS High: one shadow-casting spot, lighting mask4 / caster mask2; no realtime AO added.");}
 static void VerifySaved(){var settings=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings;int n=0;foreach(string p in Directory.GetFiles(Root+"/Scenes","*.unity")){EditorSceneManager.OpenScene(p,OpenSceneMode.Single);var c=Object.FindFirstObjectByType<ArenaCharacterGrounding>();if(!c||!c.shadowKey||c.shadowKey.shadowStrength<=0)throw new Exception("Grounding missing: "+p);if(quality(p)=="Mid"&&!c.midPipeline)throw new Exception("Mid fallback configuration missing");foreach(string dep in AssetDatabase.GetDependencies(p,true).Where(d=>d.StartsWith(Art+"/")))if(settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(dep))==null)throw new Exception("Unregistered grounding dependency: "+dep);n++;}log.Add("PASS saved scenes and dependencies="+n);}
